const pub = $('Get Publikacja').first().json;
const fields = pub.fields || pub;

const videoUrl = fields['URL Rolki (Przed publikacją)'] || pub['URL Rolki (Przed publikacją)'];
const caption = fields['Opis_TikTok'] || pub['Opis_TikTok'] || '';

const dueAt = new Date(Date.now() + 3 * 60 * 1000).toISOString();

const mutation = `mutation CreatePost($input: CreatePostInput!) {
  createPost(input: $input) {
    ... on PostActionSuccess {
      __typename
      post { id text dueAt }
    }
    ... on MutationError {
      __typename
      message
    }
  }
}`;

const variables = {
  input: {
    channelId: '68f9e1b6669affb4c98189cc',
    text: caption,
    assets: [{ video: { url: videoUrl } }],
    schedulingType: 'automatic',
    mode: 'customScheduled',
    dueAt: dueAt
  }
};

return [{
  json: { body: { query: mutation, variables } }
}];

const pub = $('Get Publikacja').first().json;
let html = pub['Treść Bloga (HTML)'] || '';
const grafikaUrl = pub['Blog_Grafika_Tresc_URL'] 
  || pub['Blog_Grafika_URL_2']  // fallback jeśli klientka nie wybrała
  || pub['Blog_Grafika_Finalna_URL'] 
  || '';

if (grafikaUrl && html.includes('<!-- GRAFIKA_TRESC -->')) {
  const imgTag = `<figure class="wp-block-image size-large"><img src="${grafikaUrl}" alt="${pub.Blog_Tytul || ''}" /></figure>`;
  html = html.replace('<!-- GRAFIKA_TRESC -->', imgTag);
}

return [{ json: { ...pub, _processed_html: html } }];

